# Create all class programs

from pathlib import Path

programs = {'class1.py': '# Student class\n\nclass Student:\n    def __init__(self, roll_no, name, marks):\n        self.roll_no = roll_no\n        self.name = name\n        self.marks = marks\n\n    def display(self):\n        percentage = sum(self.marks) / len(self.marks)\n        print("Roll No:", self.roll_no)\n        print("Name:", self.name)\n        print("Marks:", self.marks)\n        print("Percentage:", percentage)\n        print()\n\nstudents = [\n    Student(1, "Amit", [80, 75, 85]),\n    Student(2, "Rahul", [70, 82, 78]),\n    Student(3, "Sneha", [90, 88, 92])\n]\n\nfor student in students:\n    student.display()\n', 'class2.py': '# Employee salary calculation\n\nclass Employee:\n    def __init__(self, emp_id, name, basic_salary):\n        self.emp_id = emp_id\n        self.name = name\n        self.basic_salary = basic_salary\n\n    def calculate_hra(self):\n        return self.basic_salary * 0.20\n\n    def calculate_da(self):\n        return self.basic_salary * 0.10\n\n    def gross_salary(self):\n        return self.basic_salary + self.calculate_hra() + self.calculate_da()\n\n    def display(self):\n        print("Employee ID:", self.emp_id)\n        print("Name:", self.name)\n        print("Basic Salary:", self.basic_salary)\n        print("HRA:", self.calculate_hra())\n        print("DA:", self.calculate_da())\n        print("Gross Salary:", self.gross_salary())\n\nemployee = Employee(101, "Amit", 30000)\nemployee.display()\n', 'class3.py': '# Rectangle area and perimeter\n\nclass Rectangle:\n    def __init__(self, length, breadth):\n        self.length = length\n        self.breadth = breadth\n\n    def area(self):\n        return self.length * self.breadth\n\n    def perimeter(self):\n        return 2 * (self.length + self.breadth)\n\nrectangle = Rectangle(10, 5)\n\nprint("Length:", rectangle.length)\nprint("Breadth:", rectangle.breadth)\nprint("Area:", rectangle.area())\nprint("Perimeter:", rectangle.perimeter())\n', 'class4.py': '# Circle area and circumference\n\nimport math\n\nclass Circle:\n    def __init__(self, radius):\n        self.radius = radius\n\n    def area(self):\n        return math.pi * self.radius * self.radius\n\n    def circumference(self):\n        return 2 * math.pi * self.radius\n\ncircle = Circle(7)\n\nprint("Radius:", circle.radius)\nprint("Area:", circle.area())\nprint("Circumference:", circle.circumference())\n', 'class5.py': '# Book information\n\nclass Book:\n    def __init__(self, book_id, title, author, price):\n        self.book_id = book_id\n        self.title = title\n        self.author = author\n        self.price = price\n\n    def display(self):\n        print("Book ID:", self.book_id)\n        print("Title:", self.title)\n        print("Author:", self.author)\n        print("Price:", self.price)\n        print()\n\nbooks = [\n    Book(101, "Python Basics", "John", 450),\n    Book(102, "Java Programming", "James", 550),\n    Book(103, "Data Science", "David", 650)\n]\n\nfor book in books:\n    book.display()\n', 'class6.py': '# Electricity bill calculation\n\nclass ElectricityBill:\n    def __init__(self, consumer_no, consumer_name, units):\n        self.consumer_no = consumer_no\n        self.consumer_name = consumer_name\n        self.units = units\n\n    def calculate_bill(self):\n        if self.units <= 100:\n            bill = self.units * 5\n        elif self.units <= 200:\n            bill = (100 * 5) + ((self.units - 100) * 7)\n        else:\n            bill = (100 * 5) + (100 * 7) + ((self.units - 200) * 10)\n\n        return bill\n\n    def display(self):\n        print("Consumer Number:", self.consumer_no)\n        print("Consumer Name:", self.consumer_name)\n        print("Units Consumed:", self.units)\n        print("Electricity Bill:", self.calculate_bill())\n\nbill = ElectricityBill(1001, "Amit", 250)\nbill.display()\n', 'class7.py': '# Mobile phone specifications and discount\n\nclass MobilePhone:\n    def __init__(self, brand, model, storage, price):\n        self.brand = brand\n        self.model = model\n        self.storage = storage\n        self.price = price\n\n    def display_specs(self):\n        print("Brand:", self.brand)\n        print("Model:", self.model)\n        print("Storage:", self.storage)\n        print("Price:", self.price)\n\n    def discounted_price(self, discount):\n        return self.price - (self.price * discount / 100)\n\nphone = MobilePhone("Samsung", "Galaxy A55", "128 GB", 35000)\n\nphone.display_specs()\nprint("Price after 10% discount:", phone.discounted_price(10))\n', 'class8.py': '# Patient information and total bill\n\nclass Patient:\n    def __init__(self, patient_id, name, age, disease, consultation_fee):\n        self.patient_id = patient_id\n        self.name = name\n        self.age = age\n        self.disease = disease\n        self.consultation_fee = consultation_fee\n\n    def display(self):\n        print("Patient ID:", self.patient_id)\n        print("Name:", self.name)\n        print("Age:", self.age)\n        print("Disease:", self.disease)\n        print("Consultation Fee:", self.consultation_fee)\n\n    def total_bill(self, medicine_fee):\n        return self.consultation_fee + medicine_fee\n\npatient = Patient(101, "Rahul", 25, "Fever", 500)\n\npatient.display()\nprint("Total Bill:", patient.total_bill(1200))\n', 'class9.py': '# ATM menu-driven program\n\nclass ATM:\n    def __init__(self, account_no, name, balance):\n        self.account_no = account_no\n        self.name = name\n        self.balance = balance\n\n    def check_balance(self):\n        print("Balance:", self.balance)\n\n    def deposit(self, amount):\n        self.balance += amount\n        print("Amount deposited successfully.")\n\n    def withdraw(self, amount):\n        if amount <= self.balance:\n            self.balance -= amount\n            print("Amount withdrawn successfully.")\n        else:\n            print("Insufficient balance.")\n\n    def display_details(self):\n        print("Account Number:", self.account_no)\n        print("Name:", self.name)\n        print("Balance:", self.balance)\n\n\natm = ATM(10001, "Amit", 10000)\n\nwhile True:\n    print("\\n1. Check Balance")\n    print("2. Deposit Money")\n    print("3. Withdraw Money")\n    print("4. Display Account Details")\n    print("5. Exit")\n\n    choice = int(input("Enter your choice: "))\n\n    if choice == 1:\n        atm.check_balance()\n    elif choice == 2:\n        amount = float(input("Enter amount to deposit: "))\n        atm.deposit(amount)\n    elif choice == 3:\n        amount = float(input("Enter amount to withdraw: "))\n        atm.withdraw(amount)\n    elif choice == 4:\n        atm.display_details()\n    elif choice == 5:\n        print("Thank you for using ATM.")\n        break\n    else:\n        print("Invalid choice.")\n', 'class10.py': '# Vehicle rental calculation\n\nclass Vehicle:\n    def __init__(self, vehicle_no, model, rental_rate, availability=True):\n        self.vehicle_no = vehicle_no\n        self.model = model\n        self.rental_rate = rental_rate\n        self.availability = availability\n\n    def rent(self):\n        if self.availability:\n            self.availability = False\n            print("Vehicle rented successfully.")\n        else:\n            print("Vehicle is not available.")\n\n    def return_vehicle(self):\n        self.availability = True\n        print("Vehicle returned successfully.")\n\n    def rental_charges(self, days):\n        return self.rental_rate * days\n\n    def display(self):\n        print("Vehicle Number:", self.vehicle_no)\n        print("Model:", self.model)\n        print("Rental Rate:", self.rental_rate)\n        print("Available:", self.availability)\n\nvehicle = Vehicle("MH12AB1234", "Swift", 1500)\n\nvehicle.display()\nvehicle.rent()\nprint("Rental Charge for 3 days:", vehicle.rental_charges(3))\nvehicle.return_vehicle()\n', 'class11.py': '# Shopping cart with constructor and destructor\n\nclass ShoppingCart:\n    def __init__(self, customer_name, cart_id):\n        self.customer_name = customer_name\n        self.cart_id = cart_id\n        self.products = []\n\n    def add_product(self, name, price, quantity):\n        self.products.append((name, price, quantity))\n\n    def remove_product(self, name):\n        self.products = [\n            product for product in self.products\n            if product[0] != name\n        ]\n\n    def total_bill(self):\n        total = 0\n        for name, price, quantity in self.products:\n            total += price * quantity\n        return total\n\n    def display(self):\n        print("Customer:", self.customer_name)\n        print("Cart ID:", self.cart_id)\n        print("Products:", self.products)\n        print("Total Bill:", self.total_bill())\n\n    def __del__(self):\n        print("Shopping cart object destroyed.")\n\n\ncart = ShoppingCart("Amit", "C101")\n\ncart.add_product("Laptop", 50000, 1)\ncart.add_product("Mouse", 800, 2)\n\ncart.display()\n\ncart.remove_product("Mouse")\n\nprint("\\nAfter removing Mouse:")\ncart.display()\n\ndel cart\n', 'class12.py': '# Food order with constructor and destructor\n\nclass FoodOrder:\n    def __init__(self, order_id, customer_name, food_item, quantity, price):\n        self.order_id = order_id\n        self.customer_name = customer_name\n        self.food_item = food_item\n        self.quantity = quantity\n        self.price = price\n\n    def total_bill(self):\n        amount = self.quantity * self.price\n        tax = amount * 0.05\n        return amount + tax\n\n    def display(self):\n        print("Order ID:", self.order_id)\n        print("Customer Name:", self.customer_name)\n        print("Food Item:", self.food_item)\n        print("Quantity:", self.quantity)\n        print("Price:", self.price)\n        print("Total Bill including tax:", self.total_bill())\n\n    def __del__(self):\n        print("Order completed.")\n\n\norder = FoodOrder(101, "Rahul", "Pizza", 2, 250)\n\norder.display()\n\ndel order\n', 'class13.py': '# Student result with constructor and destructor\n\nclass StudentResult:\n    def __init__(self, name, marks):\n        self.name = name\n        self.marks = marks\n\n    def total(self):\n        return sum(self.marks)\n\n    def percentage(self):\n        return self.total() / len(self.marks)\n\n    def grade(self):\n        percentage = self.percentage()\n\n        if percentage >= 75:\n            return "A"\n        elif percentage >= 60:\n            return "B"\n        elif percentage >= 50:\n            return "C"\n        elif percentage >= 35:\n            return "D"\n        else:\n            return "F"\n\n    def display(self):\n        print("Student Name:", self.name)\n        print("Marks:", self.marks)\n        print("Total:", self.total())\n        print("Percentage:", self.percentage())\n        print("Grade:", self.grade())\n\n    def __del__(self):\n        print("Student result object destroyed.")\n\n\nstudent = StudentResult("Amit", [80, 75, 85, 90, 78])\n\nstudent.display()\n\ndel student\n'}

